import os, re

def load_grids():
    """Load all demo pairs and test input from the session log"""
    d = os.path.normpath(os.environ.get('RLM_SESSION_DIR', ''))
    if not d:
        return {}
    log_path = os.path.join(d, '../../sessions/' + os.path.basename(d) + '.jsonl')
    try:
        with open(log_path, 'r') as f:
            content = f.read()
    except Exception as e:
        print(f"Error loading log: {e}")
        return {}

    G = {}
    # Find patterns like "(Demo pair N input (WxH):)" or "Test input (WxH):"
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
    for m in re.finditer(pattern, content):
        key = m[1]
        h, w = int(m[2]), int(m[3])
        rows_text = content[m.end():].split('\n')[h]
        rows = [row.split() for row in rows_text.split()]
        if len(rows) == h and all(len(r) == w and all(x.isdigit() for x in r) for r in rows):
            G[key] = [[int(x) for x in row] for row in rows]
    return G

G = load_grids()
