import numpy as np

def get_components(grid):
    """Get connected components using flood fill"""
    visited = set()
    components = []

    def flood(r, c, comp_id):
        stack = [(r, c)]
        cells = []
        while stack:
            cr, cc = stack.pop()
            if (cr, cc) in visited:
                continue
            visited.add((cr, cc))
            cells.append((cr, cc))
            # Add neighbors
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = cr + dr, cc + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    if (nr, nc) not in visited and grid[nr][nc] == 2:
                        stack.append((nr, nc))
        return cells

    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == 2 and (r,c) not in visited:
                cells = flood(r, c, hash((r,c)))
                components.append(cells)

    return components

